contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        c.deposit{value: amount}();
        uint credited = c.credit(address(this));
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(!reverted && credited == amount && c.credit(address(this)) == 0 && address(c).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint valueSent) public payable {
        require(address(this).balance >= valueSent);
        uint balBefore = address(c).balance;
        bool reverted;
